import{_ as t,o,c as i,ag as a}from"./chunks/framework.HcBc_Mb9.js";const d=JSON.parse('{"title":"Effective Prompts","description":"","frontmatter":{},"headers":[],"relativePath":"ai-fluency/07-effective-prompts.md","filePath":"ai-fluency/07-effective-prompts.md"}'),n={name:"ai-fluency/07-effective-prompts.md"};function r(l,e,s,u,c,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="effective-prompts" tabindex="-1">Effective Prompts <a class="header-anchor" href="#effective-prompts" aria-label="Permalink to &quot;Effective Prompts&quot;">​</a></h1><h2 id="what-you-ll-learn" tabindex="-1">What you&#39;ll learn <a class="header-anchor" href="#what-you-ll-learn" aria-label="Permalink to &quot;What you&#39;ll learn&quot;">​</a></h2><ul><li>Understand what prompt engineering is and why it matters for productive AI collaboration</li><li>Apply six foundational prompting techniques to improve your AI interactions</li><li>Identify common patterns that lead to successful AI interactions</li><li>Troubleshoot and refine prompts when AI responses don&#39;t meet your needs</li></ul><h2 id="key-takeaways" tabindex="-1">Key takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key takeaways&quot;">​</a></h2><ul><li>Effective prompting combines clear communication principles with AI-specific techniques.</li><li>Six foundational prompting techniques: <ul><li>Give context: Be specific about what you want, why you want it, and relevant background</li><li>Show examples: Demonstrate the output style or format you&#39;re looking for</li><li>Specify constraints: Clearly define format, length, and other output requirements</li><li>Break complex tasks into steps: Guide the AI through multi-step reasoning</li><li>Ask the AI to think first: Give space for the AI to work through its process</li><li>Define the AI&#39;s role or tone: Specify how you want the AI to communicate</li></ul></li><li>The &quot;secret weapon&quot;: Ask the AI itself to help improve your prompt.<br><strong>Use other AI models to write prompts</strong></li><li>Successful prompting is iterative (and often collaborative with the AI). Expect to refine based on results</li><li>Common successful patterns include clear task overviews, format specs, explicit constraints, and relevant background information</li></ul><h2 id="effective-prompting-techniques" tabindex="-1">Effective Prompting techniques <a class="header-anchor" href="#effective-prompting-techniques" aria-label="Permalink to &quot;Effective Prompting techniques&quot;">​</a></h2><ul><li>What we want</li><li>How we want it done</li><li>How we want to interact with the AI</li></ul><h3 id="provide-context" tabindex="-1">Provide context <a class="header-anchor" href="#provide-context" aria-label="Permalink to &quot;Provide context&quot;">​</a></h3><ul><li><strong>Vague:</strong> &quot;Tell me about climate change.&quot;</li><li><strong>Specific:</strong> &quot;Explain three major impacts of climate change on agriculture in tropical regions, with examples from the past decade.&quot;</li><li><strong>Most specific:</strong> &quot;Explain three major impacts of climate change on agriculture in tropical regions, with examples from the past decade. I&#39;m preparing for a job interview at an agricultural research lab in Indonesia. I have a degree in ecology but no specific knowledge on climate change. Write a summary of key concepts that would help me speak intelligently in the interview.&quot;</li></ul><h3 id="offer-examples-of-what-good-looks-like" tabindex="-1">Offer examples of what “good” looks like <a class="header-anchor" href="#offer-examples-of-what-good-looks-like" aria-label="Permalink to &quot;Offer examples of what “good” looks like&quot;">​</a></h3><ul><li><strong>No examples:</strong> &quot;Please convert this technical statement to plain language: &#39;The platform implements end-to-end encryption protocols to safeguard data integrity.&#39;&quot;</li><li><strong>With two examples:</strong><ol><li>Original: &quot;The quantum algorithm exhibits quadratic speedup.&quot; <ul><li>Plain: &quot;The new method solves problems roughly twice as fast as previous methods.&quot;</li></ul></li><li>Original: &quot;The interface leverages intuitive design paradigms.&quot; <ul><li>Plain: &quot;The design is easy to understand and use.&quot;</li></ul></li></ol><ul><li>Now, convert this statement to plain language: &quot;The platform implements end-to-end encryption protocols to safeguard data integrity.&quot;</li></ul></li></ul><h3 id="specify-output-constraints" tabindex="-1">Specify output constraints <a class="header-anchor" href="#specify-output-constraints" aria-label="Permalink to &quot;Specify output constraints&quot;">​</a></h3><ul><li><strong>Without output specification:</strong> &quot;Design me a personal art portfolio website.&quot;</li><li><strong>With output specification:</strong> &quot;Create a clean, modern single-page portfolio website design with smooth scrolling between sections. Include these main sections: Hero, About Me, Skills, Portfolio/Projects, Experience, and Contact. Make the navigation menu sticky and responsive, with hamburger menu on mobile. Use a sunset color palette and add a dark / light mode toggle in the navigation.&quot;</li></ul><h3 id="break-complex-tasks-into-steps" tabindex="-1">Break complex tasks into steps <a class="header-anchor" href="#break-complex-tasks-into-steps" aria-label="Permalink to &quot;Break complex tasks into steps&quot;">​</a></h3><ul><li><strong>No steps:</strong> &quot;Analyze this quarterly sales data.&quot;</li><li><strong>With steps:</strong> &quot;I&#39;d like to analyze this quarterly sales data. Please approach this by: <ol><li>Looking through our sales records to identify the top-performing products</li><li>Comparing current quarter results to the previous quarter</li><li>Highlighting any unusual patterns or trends</li><li>Suggesting possible reasons for these trends&quot;</li></ol></li></ul><h3 id="define-role-style-or-tone" tabindex="-1">Define role, style, or tone <a class="header-anchor" href="#define-role-style-or-tone" aria-label="Permalink to &quot;Define role, style, or tone&quot;">​</a></h3><ul><li><strong>For explanations:</strong> &quot;Please explain how rainbows form from the perspective of an experienced science teacher speaking to a bright 10-year-old who&#39;s interested in science.&quot;</li><li><strong>For brainstorming &amp; feedback:</strong> &quot;As a UX design expert, review this website wireframe and suggest three improvements focusing on user navigation and accessibility.&quot;</li></ul>',17)])])}const f=t(n,[["render",r]]);export{d as __pageData,f as default};
